from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_date, points)
        self._pending = {}
        # customer -> list of (available_date, points) that are currently available
        # We keep all earned points, and compute balance based on day.
        # Actually, simpler: store entries (available_date, points) and redeemed total.
        self._entries = {}  # customer -> list of (available_date, points)
        self._redeemed = {}  # customer -> total points redeemed

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive.")
        points = int(amount // 10.0)
        available_date = day + timedelta(days=14)
        self._entries.setdefault(customer, []).append((available_date, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        entries = self._entries.get(customer, [])
        earned = sum(p for (d, p) in entries if d <= day)
        redeemed = self._redeemed.get(customer, 0)
        return earned - redeemed

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100.")
        if points <= 0:
            raise ValueError("Points to redeem must be positive.")
        if self.balance(customer, day) < points:
            raise ValueError("Insufficient points balance.")
        self._redeemed[customer] = self._redeemed.get(customer, 0) + points
